import React from 'react';
import './ResortDetails.css'; // Ensure this file exists and the path is correct


const ResortDetails = ({ resort }) => {
  if (!resort) {
    return <div className="error-message">No resort data available</div>;
  }

  return (
    <div className="resort-details">
      <h2>{resort.name}</h2>
      <p><strong>Location:</strong> {resort.location}</p>
      <p><strong>Condition:</strong> {resort.condition}</p>
      {/* Add more details if available */}
      {resort.fees && <p><strong>Fees:</strong> {resort.fees}</p>}
      {resort.facilities && (
        <div>
          <strong>Facilities:</strong>
          <ul>
            {resort.facilities.map((facility, index) => (
              <li key={index}>{facility}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

ResortDetails.propTypes = {
  resort: PropTypes.shape({
    name: PropTypes.string,
    location: PropTypes.string,
    condition: PropTypes.string,
    fees: PropTypes.string,
    facilities: PropTypes.arrayOf(PropTypes.string)
  })
};

export default ResortDetails;
